<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\ValueObject\Accessor\UserPersonalApiKeyCreatedAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserPersonalApiKeyCreatedAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withCreatedAt,
 * getCreatedAt/createdAt accessors, and isCreatedAtChanged with/without original.
 */
class UserPersonalApiKeyCreatedAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withCreatedAt creates a new instance with the CreatedAt set
     * from a string value, and getCreatedAt returns the primitive string.
     */
    public function testWithCreatedAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserPersonalApiKeyCreatedAtAccessorUnitTest();

        // Act
        $result = $holder->withCreatedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getCreatedAt());
    }
    /**
     * Asserts that withcreatedAt has access to the value object
     * from a string value, and getCreatedAt returns the primitive string.
     */
    public function testWithCreatedAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserPersonalApiKeyCreatedAtAccessorUnitTest();

        // Act
        $result = $holder->withCreatedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->createdAt()->value());
    }
    public function testChangedCreatedAt(): void
    {
        // Arrange
        $holder = new ImplWithUserPersonalApiKeyCreatedAtAccessorUnitTest()->withCreatedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $original = $holder->withCreatedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withCreatedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withCreatedAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $withSame = $original->isCreatedAtChanged($same);
        $withDiferent = $original->isCreatedAtChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserPersonalApiKeyCreatedAtAccessorUnitTest
{
    use UserPersonalApiKeyCreatedAtAccessor;
}
